const hours = (ctx, ed) => {
  const h = deepFind(fileJson(ctx.files, `rulebook/${ed}/policy.json`), 'fraudReviewHours');
  if (typeof h !== 'number') throw new Error(`rulebook/${ed}/policy.json has no fraudReviewHours`);
  return h;
