      ctx.call('orderflow', st.o, { op: 'ended', fid: r.ended.fid, status: r.ended.status, at: r.ended.at });
    } else if (module === 'orderflow' && r?.done) {
      // the order is over and its fulfilments are terminal: nothing is pending
    }
  }
}
