  },
  "orderflow": {
   "file": "modules/orderflow.mjs",
   "purpose": "order-level decisions: R3 customer actions on unavailable items, R4.1 readiness and starts, R4.5 outcome, R6 cancellation, R7.2 status moves",
   "rules": [
